window.RI1_UNITS = {"6":{"unit":6,"code":"RI1-U06","title":"BACKYARD DISCOVERIES","startNumber":158,"endNumber":188,"entries":[{"number":158,"term":"mammal (n)","spoken":"mammal","ipa":"mammal /ˈmæməl/","type":"noun","meaning":"động vật có vú","definition":"A warm-blooded animal whose females feed their young with milk.","note":"Đây là bốn nhóm động vật khác nhau.","example":"A whale is a mammal because it breathes air and feeds its young with milk."},{"number":159,"term":"miniature (a)","spoken":"miniature","ipa":"miniature /ˈmɪniəˌtʃʊr/","type":"adjective","meaning":"nhỏ, thu nhỏ","definition":"Very small, or made as a much smaller copy of something.","note":"","example":"The model shows a miniature version of the planned research station."},{"number":160,"term":"organism (n)","spoken":"organism","ipa":"organism /ˈɔːrɡəˌnɪzəm/","type":"noun","meaning":"sinh vật","definition":"An individual living thing, such as an animal, plant, fungus, or bacterium.","note":"","example":"Even a small garden contains thousands of living organisms."},{"number":161,"term":"soil (n)","spoken":"soil","ipa":"soil /sɔɪl/","type":"noun","meaning":"đất (trồng)","definition":"The upper layer of earth in which plants grow.","note":"","example":"Healthy soil stores water and provides nutrients for plants."},{"number":162,"term":"dwell (v) · dweller (n) ~ resident (n)","spoken":"dwell , dweller , resident","ipa":"dwell /dwɛl/ · dweller /ˈdwɛlɚ/ · resident /ˈrɛzɪdənt/","type":"verb · noun · word family","meaning":"cư trú/sinh sống · cư dân/người sinh sống","definition":"To live in a particular place; a dweller is a person or animal that lives there.","note":"dwell mang sắc thái trang trọng; dweller thường ghép với nơi sống: city dweller, cave dweller.","example":"Many tiny organisms dwell in the soil, although most garden dwellers are hard to see."},{"number":163,"term":"process (n)","spoken":"process","ipa":"process /ˈprɑːˌsɛs/","type":"noun","meaning":"quy trình","definition":"A connected series of actions or stages that produces a result.","note":"","example":"Decomposition is a natural process that returns nutrients to the soil."},{"number":164,"term":"nutrient (n) · nutrition (n)","spoken":"nutrient , nutrition","ipa":"nutrient /ˈnuːtriənt/ · nutrition /nuˈtrɪʃən/","type":"noun · word family","meaning":"chất dinh dưỡng · dinh dưỡng/quá trình cung cấp dinh dưỡng","definition":"A nutrient supports growth and health; nutrition is the process and study of obtaining nutrients.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Plants absorb each nutrient from the soil, while nutrition describes how living things obtain and use food."},{"number":165,"term":"maintain (v)","spoken":"maintain","ipa":"maintain /meɪˈnteɪn/","type":"verb","meaning":"duy trì","definition":"To keep in good condition; work that keeps something working.","note":"","example":"The school maintains its computers, and regular maintenance keeps them working."},{"number":166,"term":"coral reef","spoken":"coral reef","ipa":"coral /ˈkɔːrəl/ · reef /riːf/","type":"word / phrase","meaning":"dải san hô","definition":"A long area of rock-like coral structures formed in shallow tropical seas.","note":"","example":"A coral reef supports many species and protects the nearby coast."},{"number":167,"term":"gem (n)","spoken":"gem","ipa":"gem /dʒɛm/","type":"noun","meaning":"đá quý nói chung","definition":"A valuable stone used in jewellery, especially after it has been cut and polished.","note":"","example":"The scientist compared the bright mineral to a small blue gem."},{"number":168,"term":"species (n)","spoken":"species","ipa":"species /ˈspiːʃiz/","type":"noun","meaning":"giống loài","definition":"A group of living things of the same kind; species has the same form in the singular and plural.","note":"one species · two species; không viết specieses.","example":"The students recorded one rare species and three common species in the garden."},{"number":169,"term":"region (n) ~ area (n)","spoken":"region , area","ipa":"region /ˈriːdʒən/ · area /ˈɛriə/","type":"noun · word family","meaning":"vùng rộng ~ khu vực","definition":"A particular part of a country, area, or natural environment.","note":"region thường là vùng tương đối rộng; area là khu vực nói chung và có thể nhỏ hơn.","example":"This region has rich soil, but one small area near the road is badly polluted."},{"number":170,"term":"quality (n) # qualification (n)","spoken":"quality , qualification","ipa":"quality /ˈkwɑːləti/ · qualification /ˌkwɑːləfəˈkeɪʃən/","type":"noun · word family","meaning":"chất lượng/phẩm chất # bằng cấp/năng lực chuyên môn","definition":"A qualification proves training or ability; quality means a standard or personal characteristic.","note":"qualification là bằng cấp/năng lực được chứng nhận; quality là chất lượng hoặc phẩm chất.","example":"A teaching qualification proves professional training, whereas quality describes how good the teaching is."},{"number":171,"term":"valuable (a) · value (n) ~ invaluable (a) >< worthless (a)","spoken":"valuable , value , invaluable , worthless","ipa":"valuable /ˈvæljəbəl/ · value /ˈvælju/ · invaluable /ˌɪˈnvæljəbəl/ · worthless /ˈwɝːθləs/","type":"noun · adjective · word family","meaning":"có giá trị · giá trị ~ vô cùng quý giá >< vô giá trị","definition":"To consider something important; importance or worth; worth a lot; extremely useful; having no value.","note":"value dùng được như động từ và danh từ. invaluable nghĩa là vô cùng quý giá; trái nghĩa là worthless.","example":"The school values practical experience; its most valuable advice is invaluable to new teachers, while outdated data may be worthless."},{"number":172,"term":"precious (a)","spoken":"precious","ipa":"precious /ˈprɛʃəs/","type":"adjective","meaning":"quý giá, quý báu","definition":"Very valuable, important, or loved and therefore worth protecting.","note":"","example":"Fresh water is a precious resource in many dry regions."},{"number":173,"term":"data (n) · database (n)","spoken":"data , database","ipa":"data /ˈdeɪtə/ · database /ˈdeɪtəˌbeɪs/","type":"noun · word family","meaning":"dữ liệu · cơ sở dữ liệu","definition":"Data are recorded facts; a database is an organized electronic collection of data.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Students entered their field data into a shared scientific database."},{"number":174,"term":"contribute (v) to st · contribution (n)","spoken":"contribute to something , contribution","ipa":"contribute /kəˈntrɪbjut/ · contribution /ˌkɑːntrəˈbjuːʃən/","type":"verb · noun · phrase / pattern · word family","meaning":"đóng góp vào điều gì · sự/phần đóng góp","definition":"To give time, money, ideas, or effort to help produce a result; a contribution is what is given.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Each observation contributed to the study, and every contribution improved the final report."},{"number":175,"term":"take part in ~ join in ~ participate in","spoken":"take part in , join in , participate in","ipa":"take /teɪk/ · part /pɑːrt/ · join /dʒɔɪn/ · participate /pɑˈrtɪsəˌpeɪt/","type":"phrase / pattern · phrasal verb · verb · word family","meaning":"tham gia vào","definition":"To join an activity or become involved in it.","note":"take part in/participate in + hoạt động; join + nhóm/người hoặc join in + hoạt động.","example":"Local students took part in the survey and helped researchers collect data."},{"number":176,"term":"encourage (v) sb to do st >< discourage (v) sb from doing st · encouragement (n)","spoken":"encourage somebody to do something , discourage somebody from doing something , encouragement","ipa":"encourage /ɛˈnkɝːɪdʒ/ · discourage /dɪˈskɝːɪdʒ/ · encouragement /ɛˈnkɝːɪdʒmənt/","type":"verb · noun · phrase / pattern · word family","meaning":"khuyến khích ai làm gì >< ngăn ai làm gì · sự khuyến khích","definition":"To give support and confidence; support; to reduce confidence.","note":"encourage sb to do; discourage sb from doing. Hai động từ dùng hai giới từ/cấu trúc khác nhau.","example":"The coach encouraged us to keep trying, and his encouragement helped; he discouraged us from giving up."},{"number":177,"term":"state (v) · statement (n)","spoken":"state , statement","ipa":"state /steɪt/ · statement /ˈsteɪtmənt/","type":"verb · noun · word family","meaning":"nêu/tuyên bố · lời tuyên bố/phát biểu","definition":"To express something formally or clearly; a statement is the information expressed.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The report states that insect numbers are falling, but this statement still requires further evidence."},{"number":178,"term":"involve (v) · be involved in","spoken":"involve , be involved in","ipa":"involve /ˌɪˈnvɑːlv/ · involved /ˌɪˈnvɑːlvd/","type":"verb · word family","meaning":"bao gồm/liên quan đến · tham gia vào/dính líu đến","definition":"To include or affect someone or something.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The project involves students from three schools."},{"number":179,"term":"observe (v) · observation (n)","spoken":"observe , observation","ipa":"observe /əˈbzɝːv/ · observation /ˌɑːbzɚˈveɪʃən/","type":"verb · noun · word family","meaning":"quan sát · sự/nhận xét quan sát","definition":"To watch or examine something carefully; an observation is something noticed or recorded.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Researchers observed the birds and recorded each observation in a field notebook."},{"number":180,"term":"award (n,v) ~ reward (n,v)","spoken":"award , reward","ipa":"award /əˈwɔːrd/ · reward /rɪˈwɔːrd/","type":"verb · noun · word family","meaning":"giải thưởng/trao giải ~ phần thưởng/thưởng công","definition":"An award recognizes achievement; a reward is given in return for effort, help, or good behaviour.","note":"award gắn với thành tích được công nhận; reward là phần thưởng đáp lại hành động, nỗ lực hoặc thông tin.","example":"The scientist received an award for her discovery and a financial reward for solving the technical problem."},{"number":181,"term":"base (v) on…","spoken":"base on…","ipa":"base /beɪs/","type":"verb","meaning":"dựa trên …","definition":"To use a fact, idea, or situation as the main foundation for a decision or conclusion.","note":"","example":"The conclusion is based on observations collected over three years."},{"number":182,"term":"confirm (v)","spoken":"confirm","ipa":"confirm /kəˈnfɝːm/","type":"verb","meaning":"xác nhận","definition":"To show or state that something is true, correct, or certain.","note":"","example":"A second survey confirmed that the rare species still lived in the region."},{"number":183,"term":"current (a) · currently (adv)","spoken":"current , currently","ipa":"current /ˈkɝːənt/ · currently /ˈkɝːəntli/","type":"adjective · adverb · word family","meaning":"hiện tại/hiện thời · hiện nay","definition":"Belonging to the present time; currently means at the present time.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The current plan is temporary, and the team is currently testing a safer approach."},{"number":184,"term":"develop (v) · development (n)","spoken":"develop , development","ipa":"develop /dɪˈvɛləp/ · development /dɪˈvɛləpmənt/","type":"verb · noun · word family","meaning":"phát triển · sự phát triển","definition":"To grow, change, or improve over time; development is that process.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Young insects develop rapidly, and their development depends on temperature."},{"number":185,"term":"number (n) ~ amount (n) · the number of …","spoken":"number , amount , the number of …","ipa":"number /ˈnʌmbɚ/ · amount /əˈmaʊnt/","type":"noun · word family","meaning":"số lượng của thứ đếm được ~ lượng của thứ không đếm được · số lượng của…","definition":"Amount is used mainly with uncountable nouns; number is used with countable nouns.","note":"amount of + danh từ không đếm được; number of + danh từ đếm được số nhiều.","example":"Use amount with uncountable nouns, such as money, and number with countable nouns, such as items."},{"number":186,"term":"collective (a) · collective knowledge","spoken":"collective , collective knowledge","ipa":"collective /kəˈlɛktɪv/ · knowledge /ˈnɑːlədʒ/","type":"adjective · word family","meaning":"chung/tập thể · tri thức chung của tập thể","definition":"Shared by all members of a group rather than belonging to one individual.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The project combined the collective knowledge of researchers and local residents."},{"number":187,"term":"conference (n)","spoken":"conference","ipa":"conference /ˈkɑːnfɚəns/","type":"noun","meaning":"cuộc hội thảo","definition":"A formal meeting at which people discuss a subject, often over several sessions.","note":"","example":"Scientists presented their findings at an international conference."},{"number":188,"term":"responsible (a) for st · responsibility (n)","spoken":"responsible for something , responsibility","ipa":"responsible /riˈspɑːnsəbəl/ · responsibility /riˌspɑːnsəˈbɪləti/","type":"noun · adjective · phrase / pattern · word family","meaning":"chịu trách nhiệm về điều gì · trách nhiệm","definition":"Having a duty for something; a duty to deal with something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: responsible (a) for st · responsibility (n)","example":"The council is responsible for road safety and accepts this responsibility."}],"pronunciationFocus":[{"entryNumber":164,"points":[{"category":"word-stress","note":"nutrient nhấn âm đầu; nutrition nhấn trọng âm chính ở âm thứ hai"}]},{"entryNumber":174,"points":[{"category":"word-stress","note":"contribute nhấn /ˈtrɪb/; contribution chuyển trọng âm chính sang /ˈbjuː/"}]},{"entryNumber":175,"points":[{"category":"linking","note":"participate‿in: nối /t/ cuối participate với nguyên âm đầu của in"}]},{"entryNumber":177,"points":[{"category":"final-sound","note":"statement /ˈsteɪtmənt/: giữ rõ /t/ ở cuối"}]},{"entryNumber":178,"points":[{"category":"final-sound","note":"involved /ˌɪˈnvɑːlvd/: giữ đủ cụm /lvd/ ở cuối"},{"category":"linking","note":"involved‿in: nối /d/ cuối involved với nguyên âm đầu của in"}]},{"entryNumber":186,"points":[{"category":"silent-letter","note":"knowledge /ˈnɑːlədʒ/: chữ k đầu từ không được phát âm"}]},{"entryNumber":188,"points":[{"category":"word-stress","note":"responsible nhấn /ˈspɑːn/; responsibility chuyển trọng âm chính sang /ˈbɪl/"}]}]}};
